import{_ as o,o as d,c as t,ag as a}from"./chunks/framework.DaCm-iTo.js";const f=JSON.parse('{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/commands.md","filePath":"en/modules/forge/commands.md","lastUpdated":null}'),r={name:"en/modules/forge/commands.md"};function i(s,e,c,n,m,l){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to &quot;Commands and Permissions&quot;">​</a></h1><p>The main command of EmakiForge is <code>/emakiforge</code>, with <code>/eforge</code> and <code>/ef</code> as aliases. Commands open the forge GUI, open the recipe book, list recipes, reload configuration, and print debug information.</p><p>The root command requires <code>emakiforge.use</code> (default true). Additional subcommand permissions are listed below.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ef help</code></td><td>Root permission only</td><td>Show command help. Running the root command with no arguments also shows help.</td></tr><tr><td><code>/ef forge</code></td><td>Root permission only</td><td>Open the forge GUI. Players only.</td></tr><tr><td><code>/ef book</code></td><td><code>emakiforge.book</code> or <code>emakiforge.admin</code></td><td>Open the recipe book. Players only.</td></tr><tr><td><code>/ef list recipe</code></td><td><code>emakiforge.admin</code></td><td>List loaded recipes with display names. <code>recipes</code> is also accepted, but tab completion only suggests <code>recipe</code>.</td></tr><tr><td><code>/ef reload</code></td><td><code>emakiforge.reload</code> or <code>emakiforge.admin</code></td><td>Reload config, language, GUI templates, and recipes.</td></tr><tr><td><code>/ef debug stats</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Print runtime metrics and the recipe load report (<code>status</code> is equivalent).</td></tr><tr><td><code>/ef debug &lt;player|module|...&gt;</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Delegate to the CoreLib debug command.</td></tr></tbody></table><p>Available debug submodules: <code>recipe</code>, <code>forge</code>, <code>gui</code>, <code>pdc</code>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiforge.use</code></td><td>true</td><td>Allows use of the root command and forge GUI.</td></tr><tr><td><code>emakiforge.book</code></td><td>true</td><td>Allows opening the recipe book.</td></tr><tr><td><code>emakiforge.reload</code></td><td>op</td><td>Allows reloading configuration.</td></tr><tr><td><code>emakiforge.debug</code></td><td>op</td><td>Allows debug output.</td></tr><tr><td><code>emakiforge.admin</code></td><td>op</td><td>Allows administrative operations.</td></tr></tbody></table>',7)])])}const g=o(r,[["render",i]]);export{f as __pageData,g as default};
